"""Packing clock: shift windows, pack rates and remaining copies, read from the portal files.

The launch plan workbook holds a shift table (rows like 'Saturday | 06:00–22:00') and an editions
table (product, packed, rate per hour). Sheets and columns are found by their headers, so a new
version of the plan is read without code changes. Packed copies come from the pack-out log when it
is newer than the plan. Nothing about Soony is written here.
"""

from __future__ import annotations

import csv
import re
from dataclasses import dataclass, field
from datetime import date, datetime, timedelta
from pathlib import Path
from typing import Any
from zoneinfo import ZoneInfo

_TIMES = re.compile(r"(\d{1,2}):(\d{2})\s*[–—-]\s*(\d{1,2}):(\d{2})")
WEEKDAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]


@dataclass
class EditionPlan:
    product: str
    label: str | None = None
    day_one: float | None = None
    packed: float | None = None
    rate_per_hour: float | None = None

    @property
    def remaining(self) -> float | None:
        if self.day_one is None or self.packed is None:
            return None
        return max(self.day_one - self.packed, 0)


@dataclass
class PackClock:
    windows: list[tuple[datetime, datetime]] = field(default_factory=list)
    editions: dict[str, EditionPlan] = field(default_factory=dict)

    def hours_left(self, now: datetime) -> float:
        return sum(max((e - max(s, now)).total_seconds(), 0) for s, e in self.windows) / 3600

    def after_packing_hours(self, now: datetime, hours: float) -> datetime | None:
        """Wall-clock time once `hours` of packing from `now` are used up; None if they outlast
        the last shift. Night gaps between shifts are skipped."""
        left = max(hours, 0.0)
        for start, end in self.windows:
            begin = max(start, now)
            if begin >= end:
                continue
            avail = (end - begin).total_seconds() / 3600
            if left <= avail:
                return begin + timedelta(hours=left)
            left -= avail
        return None

    def line_stops(self, now: datetime, product: str | None, copies_short: float | None):
        """When a line runs out if `copies_short` of the remaining copies cannot be packed: it packs
        the others at its plan rate, inside shifts, then stops. None if nothing is short or the
        rate is unknown."""
        ed = self.editions.get(product or "")
        if not ed or not copies_short or not ed.rate_per_hour or ed.remaining is None:
            return None
        packable = max(ed.remaining - copies_short, 0)
        return self.after_packing_hours(now, packable / ed.rate_per_hour)

    def slack_hours(self, now: datetime, product: str | None) -> float | None:
        ed = self.editions.get(product or "")
        if not ed or not ed.rate_per_hour or ed.remaining is None:
            return None
        return round(self.hours_left(now) - ed.remaining / ed.rate_per_hour, 1)


def _num(v: Any) -> float | None:
    if v is None or v == "":
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace(" ", "")
    if re.fullmatch(r"-?\d{1,3}(\.\d{3})+", s):  # '42.900' = 42,900
        s = s.replace(".", "")
    try:
        return float(s.replace(",", ""))
    except ValueError:
        return None


def _rows(path: Path) -> dict[str, list[tuple]]:
    try:
        import openpyxl

        wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
    except Exception:  # unreadable or missing workbook: no plan
        return {}
    out = {ws.title: [r for r in ws.iter_rows(values_only=True) if any(c is not None for c in r)]
           for ws in wb.worksheets}
    wb.close()
    return out


def _table(rows: list[tuple], *needles: str) -> tuple[dict[str, int], list[tuple]] | None:
    """The first header row that names every needle, with the rows below it."""
    for i, r in enumerate(rows):
        cells = [str(c or "").strip().lower() for c in r]
        if all(any(n in c for c in cells) for n in needles):
            return {c: j for j, c in enumerate(cells) if c}, rows[i + 1:]
    return None


def _col(header: dict[str, int], *needles: str) -> int | None:
    return next((j for c, j in header.items() if all(n in c for n in needles)), None)


def _windows(rows: list[tuple], launch: date | None, tz: ZoneInfo):
    found = _table(rows, "day", "shift")
    if not found or not launch:
        return []
    header, body = found
    dcol, scol = _col(header, "day"), _col(header, "shift")
    out = []
    for r in body:
        day = str(r[dcol] or "").strip().lower() if dcol is not None else ""
        m = _TIMES.search(str(r[scol] or "")) if scol is not None else None
        if day not in WEEKDAYS or not m:
            continue
        on = launch - timedelta(days=(launch.weekday() - WEEKDAYS.index(day)) % 7)
        h1, m1, h2, m2 = map(int, m.groups())
        start = datetime(on.year, on.month, on.day, h1, m1, tzinfo=tz)
        end = datetime(on.year, on.month, on.day, h2, m2, tzinfo=tz)
        out.append((start, end if end > start else end + timedelta(days=1)))
    return sorted(out)


def _read_csv(path: Path) -> list[dict]:
    try:
        with path.open(encoding="utf-8-sig", newline="") as fh:
            return list(csv.DictReader(fh))
    except OSError:
        return []


def _read_editions(rows: list[tuple], editions: dict[str, EditionPlan]) -> None:
    """Rates and packed copies from any table that lists launch products by id."""
    for i, r in enumerate(rows):
        cells = [str(c or "").strip().lower() for c in r]
        pc = next((j for j, c in enumerate(cells) if c in ("product", "material", "product id")), None)
        if pc is None:
            continue
        header = {c: j for j, c in enumerate(cells) if c}
        title = " ".join(str(c or "") for row in rows[:i] for c in row).lower()
        rc = _col(header, "rate")
        kc = header.get("packed")
        if kc is None and "packed" in title:
            kc = header.get("qty")
        for row in rows[i + 1:]:
            pid = str(row[pc] or "").strip() if pc < len(row) else ""
            if pid not in editions:
                continue
            ed = editions[pid]
            if rc is not None and _num(row[rc]):
                ed.rate_per_hour = _num(row[rc])
            if kc is not None and _num(row[kc]) is not None:
                ed.packed = max(ed.packed or 0, _num(row[kc]))


def load(root: Path | None, tz: ZoneInfo) -> PackClock:
    if root is None:
        return PackClock()
    soony = root / "soony"
    products = _read_csv(soony / "master" / "products.csv")
    launch_products = {p["product_id"]: p for p in products if p.get("lifecycle") == "launch"}
    launch_dates = sorted(p.get("launch_date") for p in launch_products.values() if p.get("launch_date"))
    launch = date.fromisoformat(launch_dates[0]) if launch_dates else None

    editions: dict[str, EditionPlan] = {
        pid: EditionPlan(pid, p.get("name"), _num(p.get("day_one_qty"))) for pid, p in launch_products.items()
    }
    windows: list[tuple[datetime, datetime]] = []
    books = [b for d in ("context", "erp") if (soony / d).is_dir() for b in sorted((soony / d).glob("*.xlsx"))]
    for book in books:
        for rows in _rows(book).values():
            windows = windows or _windows(rows, launch, tz)
            _read_editions(rows, editions)
    # Packed copies only grow, so the highest figure across the plan, status sheets and the
    # pack-out log is the newest one.
    packed: dict[str, float] = {}
    for f in sorted((soony / "erp").glob("packout_log*.csv")) if (soony / "erp").is_dir() else []:
        for r in _read_csv(f):
            if r.get("product_id") in editions:
                packed[r["product_id"]] = packed.get(r["product_id"], 0) + (_num(r.get("units_packed")) or 0)
    for pid, n in packed.items():
        editions[pid].packed = max(editions[pid].packed or 0, n)
    return PackClock(windows, editions)
export type Level = 'red' | 'amber' | 'grey' | 'blue'

export interface Option {
  index: number
  action?: string
  cost?: string
  effect?: string
  recommended: boolean
  draft?: string
  to?: string
  channel?: string
  routine_type?: string | null
}
export interface Evidence {
  source?: string
  value?: string | number
  doc?: string
  page?: number
  quote?: string
  translation?: string
  language?: string
  unit?: string
}
export interface TrailStep { agent?: string; at?: string; text?: string }

export interface Card {
  id: string
  kind?: string
  part?: string
  headline: string
  summary?: string
  number: number | null
  number_label: string
  edition?: string
  cell_hours_lost?: number
  slack_hours?: number
  deadline?: string
  runs_dry?: string | null
  severity?: string
  level: Level
  status: string
  approver?: string
  routed_to_other: boolean
  reason?: string
  called_at?: string
  options: Option[]
  evidence: Evidence[]
  trail: TrailStep[]
  supplier_id?: string
  supplier_name?: string
  shipment?: string
  routes: string[]
  ui: {
    status?: string; at?: string; note?: string
    // Supplier reply tied back by the alert agent (replies.py)
    reply?: string; reply_from?: string; reply_at?: string; reply_text?: string
  }
  escalation_brief: string
}

export interface MapNode { id: string; kind: 'supplier' | 'port' | 'dc' | 'site'; name: string; lat: number; lon: number; country?: string }
export interface Leg { id: string; origin: string; destination: string; mode: string; via?: string; path: [number, number][] | null }
export interface Shipment {
  id: string; route_id: string; mode: string; supplier_id: string; status: string
  eta?: string; etd?: string; progress: number; departed: boolean; silent: boolean; silent_hours?: number
  level: Level; note?: string
}
export interface StripItem {
  edition: string; label: string; level: Level; status: string
  copies_at_risk: number; slack_hours: number | null
  breaks_first: { text?: string; deadline?: string; stops_at?: string | null; card: string } | null
}
export interface EventItem { id: string; at: string; path?: string; file?: string; node?: string }
export interface ActivityItem {
  at?: string; text: string; kind: string; detail?: string | null; card?: string
  /** Who handled it: "inbox", "voice" or "routine: <name>". Missing on older items. */
  via?: string | null
}

export interface State {
  now: string
  viewer: string
  portal_found: boolean
  map: { nodes: MapNode[]; legs: Leg[]; version: string }
  route_level: Record<string, Level>
  badges: Record<string, number>
  shipments: Shipment[]
  strip: StripItem[]
  cards: Card[]
  inbox_ids: string[]
  calm: boolean
  events: EventItem[]
  activity: ActivityItem[]
  last_drop_at: string | null
  last_check_at: string | null
  read_since_6: number
  trust: Record<string, string>
}

export async function fetchState(): Promise<State> {
  const r = await fetch('/api/state')
  if (!r.ok) throw new Error(`state ${r.status}`)
  return r.json()
}

export async function post<T = unknown>(url: string, body: unknown = {}): Promise<T> {
  const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  if (!r.ok) throw new Error(`${url} ${r.status}`)
  return r.json()
}

export const COLORS: Record<Level, string> = {
  blue: '#1d6fe0',
  amber: '#d97706',
  red: '#dc2626',
  grey: '#7b8494',
}
export const LEVEL_RANK: Record<Level, number> = { red: 3, amber: 2, grey: 1, blue: 0 }

const TZ = 'Europe/Berlin'
export const fmtTime = (iso?: string | null) =>
  iso ? new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: TZ }).format(new Date(iso)) : ''
export const fmtDay = (iso?: string | null) =>
  iso ? new Intl.DateTimeFormat('en-GB', { weekday: 'short', timeZone: TZ }).format(new Date(iso)) : ''
export const fmtNum = (n: number | null | undefined) => (n == null ? '–' : Math.round(n).toLocaleString('en-GB'))

export function ago(iso: string | null | undefined, nowMs: number): string {
  if (!iso) return 'never'
  const min = Math.max(0, Math.round((nowMs - new Date(iso).getTime()) / 60000))
  if (min < 1) return 'just now'
  if (min < 60) return `${min} min ago`
  const h = Math.floor(min / 60)
  return h < 48 ? `${h} h ago` : `${Math.floor(h / 24)} days ago`
}

export function until(iso: string | undefined, nowMs: number): { text: string; urgent: boolean } | null {
  if (!iso) return null
  const min = Math.round((new Date(iso).getTime() - nowMs) / 60000)
  if (min <= 0) return { text: 'now', urgent: true }
  const text = min < 60 ? `${min} min` : `${Math.floor(min / 60)} h ${min % 60 ? `${min % 60} min` : ''}`.trim()
  return { text: `in ${text}`, urgent: min < 180 }
}

export const DONE_WORD: Record<string, string> = {
  approved: 'Approved', sent: 'Sent', escalated: 'Escalated', dismissed: 'Dismissed',
}
export const DECIDED = Object.keys(DONE_WORD)

/** What handled an activity item, read from its `via` field. */
export function viaOf(a: ActivityItem): { kind: 'routine'; name: string } | { kind: 'voice' } | null {
  const v = (a.via ?? '').trim()
  if (/^routine\s*:/i.test(v)) return { kind: 'routine', name: v.replace(/^routine\s*:\s*/i, '') }
  if (/^voice$/i.test(v)) return { kind: 'voice' }
  return null
}

// Internal part / product codes (CMP-GAM-001, FG-GH6-STD): never shown on their own.
const CODE = /^[A-Z]{2,5}(-[A-Z0-9]+)+$/

/** A readable name for a part code, found on the cards; undefined if none has one. */
export function partName(part: string | undefined, cards: Card[]): string | undefined {
  if (!part) return undefined
  if (!CODE.test(part)) return part
  const c = cards.find(
    (c) => c.part && !CODE.test(c.part) && (c.id.endsWith(part) || c.options.some((o) => o.action?.includes(`(${part})`))),
  )
  return c?.part
}

const fmtDate = (ymd: string) =>
  new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' }).format(
    new Date(`${ymd}T00:00:00Z`),
  )

/** Display text: drop bracketed internal codes, write ISO dates as "Mon 23 Nov". */
export function tidy(t: string | undefined | null): string {
  if (!t) return ''
  return t
    .replace(/\s*\((?:[A-Z]{2,5}-)+[A-Z0-9-]+\)/g, '')
    .replace(/\b(\d{4}-\d{2}-\d{2})(?:T[\d:.]+(?:Z|[+-]\d{2}:\d{2})?)?\b/g, (_, d: string) => fmtDate(d))
}

const cap = (t: string) => (t ? t[0].toUpperCase() + t.slice(1) : t)

/** One cost wording everywhere. */
export function costText(cost: string | undefined | null): string {
  const c = (cost ?? '').trim()
  if (!c || /^(none|no cost|free|0|-|–|n\/a)$/i.test(c)) return 'No cost'
  return cap(tidy(c))
}
export const sentence = (t: string | undefined | null) => cap(tidy(t))

/** Slack as people say it; "–" when it would only confuse (on track, or nothing at risk). */
export function slackText(hours: number | null, onTrack: boolean, atRisk: number): string {
  if (hours == null || (onTrack && (hours < 0 || atRisk === 0))) return '–'
  const sign = hours < 0 ? '−' : ''
  const a = Math.abs(hours)
  if (a < 1) return `${sign}${Math.round(a * 60)} min`
  return `${sign}${Math.round(a * 10) / 10} h`
}
@import "@fontsource-variable/inter";
@import "tailwindcss";

@theme {
  --font-sans: "Inter Variable", Inter, ui-sans-serif, system-ui, sans-serif;
  --color-ink: #0f172a;
  --color-ink-2: #475569;
  --color-ink-3: #64748b;
  --color-line: #e2e8f0;
  --color-panel: #f8fafc;
  --color-ok: #1d6fe0;
  --color-warn: #d97706;
  --color-stop: #dc2626;
  --color-silent: #7b8494;
  --color-land: #eceff3;
}

html, body, #root { height: 100%; }
body {
  background: #fff;
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-feature-settings: "tnum" 1, "cv11" 1;
  -webkit-font-smoothing: antialiased;
}

@keyframes pulse-ring {
  0% { r: 5px; opacity: .9; }
  100% { r: 20px; opacity: 0; }
}
.pulse-ring { animation: pulse-ring 1.6s ease-out infinite; }
.pulse-once { animation: pulse-ring 1.2s ease-out 3; }
.pulse-once.delay { animation-delay: .5s; }

@keyframes recolour {
  0% { stroke-width: 7px; }
  100% { stroke-width: 2.75px; }
}
.route-recolour { animation: recolour 1.2s ease-out; }

@keyframes slide-in {
  from { opacity: 0; transform: translateY(-14px); }
  to { opacity: 1; transform: none; }
}
.slide-in { animation: slide-in .45s ease-out; }

@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, -8px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}
.toast-in { animation: toast-in .25s ease-out; }

